svg.script:
var YV = {x:0, y:0, w:1400, h:920};
var YS = null;

function yApply() {
  if (YS) { YS.setAttribute('viewBox', YV.x+' '+YV.y+' '+YV.w+' '+YV.h); }
}
function yResetZoom() {
  YV = {x:0, y:0, w:1400, h:920};
  yApply();
}
function showView(id) {
  var gs = document.querySelectorAll('.view');
  for (var i = 0; i < gs.length; i++) {
    gs[i].style.display = (gs[i].id === id) ? 'inline' : 'none';
  }
  yResetZoom();
}
function zoomIn() {
  var cx = YV.x + YV.w/2, cy = YV.y + YV.h/2;
  var w = YV.w/1.25, h = YV.h/1.25;
  if (w < 320) return;
  YV = {x:cx-w/2, y:cy-h/2, w:w, h:h};
  yApply();
}
function zoomOut() {
  var cx = YV.x + YV.w/2, cy = YV.y + YV.h/2;
  var w = YV.w*1.25, h = YV.h*1.25;
  if (w > 3200) return;
  YV = {x:cx-w/2, y:cy-h/2, w:w, h:h};
  yApply();
}
function resetView() {
  showView('view-top');
}
function yInit() {
  YS = document.documentElement;
  showView('view-top');
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', yInit);
} else {
  yInit();
}
